where s.slug = 'devi-navaratrula-jnanam' and d.day_number = 6 and d.language = 'te'
on conflict (day_id, section_order) do update
set id = excluded.id, title = excluded.title, content = excluded.content, minutes = excluded.minutes, updated_at = now();

insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'cf3f8778-42ac-4e68-a817-108cbfbba8e8'::uuid,
  d.id,
  6,
  $d6tes6title$సాయుజ్యం · త్రిశూలం$d6tes6title$,
  $d6tes6json$["స్థితి ఈ త్రిగుణ దోషాల్ని సంహరించి దాటి అతీతంగా ఉన్నటువంటి తురీయ స్థితి ఆ స్థితిలో ఇప్పుడు ట్యూన్ అయిపోదాం కంప్లీట్ గా సాయుదజ్యం అమ్మవారే మనం అయిపోదాం అమ్మవారే మనం ఇంతవరకు మనం అమ్మని దర్శించాం బాహ్యం నుంచి ఇప్పుడు సాహిత్యంలో మనం అమ్మ మనం ఒకటే అయిపోదాం ఒకప్పుడు ఒకటిగానే ఉన్నాం మన చిన్నప్పుడు తల్లి గర్భంలో మనం శిశువుగా ఉన్నప్పుడు ఒక పిండంగా ఉన్నప్పుడు మనం మన తల్లి మనం వేరు కాదు ఆ తల్లి గర్భంలో మనం ఉన్నాం అలానే ఇప్పుడు ఆ తల్లి మనం వేరు కాదనే ఈ స్థితిలో ఉన్నాం ఏకత్వ స్థితిలో","ఉన్నాం ఆ తల్లే మనం అయిపోదాం మీలో మీలో ఉన్నటువంటి ఎనర్జీని గమనించండి మీరు త్రిశూ సూలం పట్టుకుంటే ఎలా ఉంటుందో పట్టుకునే చూడండి.","మీ చేతిలో ఒక త్రిశూలాన్ని సంకేత రూపంలో భావన చేయండి. మీరు ఆ త్రిశూలాన్ని పట్టుకుంటే ఎలా ఉంటుందో ఆ భావన చేయండి. ఆ అనుభూతిని చెందండి. నేను నా తమోగుణ రజోగుణ సత్వ గుణ దోషాలను దాటి త్రిగుణాతీత స్థితిలో నేను ఉన్నటువంటి శక్తి స్వరూపుని నేను జాగృత స్వప్న సుషుప్తావస్థలను దాటి ఉన్నటువంటి తురియా స్థితిలో ఉన్నటువంటి శక్తి స్వరూపుని ఈ భావనతో మనం ఉందాం ఏ సాయుదజ్యం కంప్లీట్ గా మన అమ్మవారు మనం ఒకటే ఆ ఎనర్జీ పాస్చర్ లో మనం ఉందాం.","ఒక్క నిమిషం ఓకే మై డియర్ ఫ్రెండ్స్ నిదానంగా తిరిగి జాగ్రత్త అవస్థలోకి తిరిగి వచ్చేద్దాం దట్స్ వండర్ఫుల్ ఫ్రెండ్స్ ఇప్పుడు మనం చక్కగా ఒక జగన్మాత ఈ దేవీ శక్తిని ఒక ఛాంట్ హారికా మేడం ద్వారా మనం విందాం. థాంక్యూ సార్.","సహస్రారసరోజంమే కురుబిందుమయంతే చక్రాగ్రం సహస్రారసరోజంమే కురుబిందుమయంతే చక్రాగ్రం అభిన్న నిజాత్మ పరాత్మ విశుద్ధ స్వరూప విరాజితాత్వాంహి అభిన్న నిజాత్మ పరాత్మ విశుద్ధ స్వరూప విరాజితాత్వాంహి శ్రీ రాజరాజ రాజేశ్వరి సదయే చిన్మాత్రికే పాహిని శ్రీరాజరాజేసిమాం [పాడటం] కృపయ చిత్కుండజేపాలయ శ్రీ రాజరాజేశ్వరి [పాడటం] సదయే చిన్మాత్రికే పాహిమ శ్రీరాజరాజేసిమా [పాడటం] కృపయ చిక్కుండజేపాలయ ముద్రా సాఖిలయోనిస్తే నత బృందావని విఖ్యాత ముద్రా సాఖిలయోనెస్తే నత బృందావని విఖ్యాత పంచబ్రహ్మమహి [పాడటం]","శివశంకర రిశాంతరసా సచ్చిదానంద పంచబ్రహ్మమహి శివ శంకరి శాంతరసా సచ్చిదానంద శ్రీ రాజరాజేశ్వరి [పాడటం] సదయే చిన్మాత్రికే పాహిమ శ్రీ రాజరాజేసిమాం కృపయా చిత్కుండజేపాలయ సర్వానందమయి చక్రే త్రైపుర సుందరి త్వంహాసి సర్వానందమయి చక్రే త్రైపుర సుందరిత్వంహాసి యోగిన్యస్తు పరాత్పర పూర్వక రాహస్య అనుయాంతిత్వం యోగిన్యస్తు పరాత్పర పూర్వక రాహస్య అనుయాంతిత్వం శ్రీ రాజరాజేశ్వరి [పాడటం] సదయే చిన్మాత్రికే పాహిని శ్రీరాజరాజేసిమా [పాడటం] కృపయ చిత్కుండజే పాలయ సతయే చిన్మాత్రికే పాహిమ కృపయ చిక్కుండజే పాలయ","థాంక్యూ హరిక మేడం వండర్ఫుల్ వండర్ఫుల్ వండర్ఫుల్ కొన్ని షేరింగ్ చేసుకుందాం ఎస్ సార్ మూడే ఆగి సార్ నమస్కారం సార్ నమస్కారం అండి నమస్కారం మీతో మాట్లాడడం ఒక అదృష్టంగా భావిస్తున్నాను సార్ ఓకే నేను ఎన్నో రోజుల నుంచి సాలోక్యము సామిప్యము ఈ లోకములోనివే కదని ఒక పాట పాడుతుంటాను సార్ ఇంత వివరంగా ఈరోజు అర్థమైంది సార్ దాని అర్థం చాలా రోజులు నుండి పాట పాడుతున్నా దాని అర్థం ఎవరు చెప్పేవారు లేరు సార్ చాలా ఆనందంగా ఉంది సార్ ఈరోజు వండర్ఫుల్ అదేవిధంగా దుర్గామాత పైన కూడా అమ్మవారు కోళ్లు కోస్తారు","గోల్డ్ కోస్తారు ఈమె అంత పూజించవలసిన అవసరం ఏందనే భావనలో ఉన్నాను సార్ నేను ఈ తొమ్మిది రోజుల నుంచి ఈ క్లాస్ చాలా నుంచి ఆమె గురించి చాలా వివరంగా [గొంతు సవరించుకోవడం] తెలుసుకున్నాను.","ఆ సమర్పణ భావంతో ప్రతిరోజు సాధన చేస్తున్నాను సార్ [గొంతు సవరించుకోవడం] అలాగే నవంబర్ 24 వాలంటరీగా వస్తాను సార్ నేను ఓకే సార్ ఇంకు వేరేవాళ్ళ వెల్కమ్ సార్ వెల్కమ్ వెల్కమ్ చక్కగా రండి ఓకే సార్ సేవ చేసుకోవాలి థాంక్యూ వండర్ఫుల్ ఓకే సార్ థాంక్యూ సార్ నిన్న ధనా గారు హ్యాండ్ రైస్ చే యా ధనా గారు నమస్తే న్యూటన్ సార్ నమస్కారం నమస్కారం మిమ్మల్ని ఫస్ట్ టైం ఫిజికల్ గా కలిసాను సార్ ఇక్కడ హైదరాబాద్లో జాతీయ అహింసా ఈవెంట్ లో సో చాలా హ్యాపీ అనిపించింది.","సో ఈ ఆరు రోజుల క్లాస్ నాకు చాలా బాగా బాగా ఫీల్ అవ్వగలుగుతున్నాను సార్ సో ఐ యామ్ టేకింగ్ అప్ ఎవ్రీథింగ్ మీరు అన్నారు కదా సూక్ష్మంగా కూడా అహంకారం ఉంటుందని ఆ సమర్పణ సాధనలో చాలా వరకు వెళ్ళిపోతుంది.","మా మదర్ తో కూడా నేను నాన్ వైలెంట్ గా వైలెంట్ లేకుండా బాగా మాట్లాడగలుగుతున్నాను సర్ నౌ వి ఆర్ మేకింగ్ ఏ గుడ్ కనెక్షన్ సర్ సో ఐ యమ్ సో హ్యాపీ అంటే ఆవిడ కొంచెం తిడుతున్నా కూడా అక్కడ ఎక్కడో ప్రేమ ఉంది సర్ సో దాన్ని పట్టుకుంటే చాలా ఈజీగా ఉంది సర్ కనెక్షన్ సో ఎక్సలెంట్ నా ప్రశ్న ఆ ధ్యానంలో స్టార్టింగ్ లో ఆ ఉద్రృతికి నేను భయపడేవాడిని ఆ అలా రావడము అరే ఏంటిది అప్పుడు నాకు జ్ఞానం సరిగా లేదు సార్ మ్ భయపడేవాన్ని తిట్టుకునేవాడిని ఏంటి ఈ శక్తి ఇంతలా ఇబ్బంది పడుతుంది అబ్బా అని ఇప్పుడు","ఏంటంటే ఎంత ఉద్రృతి ఉన్నా హ్యాపీగానే ఉంది ఎంత ఫోర్స్ వచ్చినా ఎంతలా ఎంతలా రిపేర్ చేస్తున్న హాయిగా ఉంది అరేయ్ మనిషాశున్నే వదించిన అమ్మ ఈ ఇంటర్నల్ బ్లాక్స్ ఒక లెక్కేనా వెళ్ళిపోతుంది అన్నంతగా సరెండర్ అయిపోయాను సార్ ఆ విధంగా ఇక్కడ లేదన్నమాట సో ఈవెన్ నిద్రలో కూడా నాకు ఏవో డ్రీమ్స్ వస్తున్నాయి చక్కగా చూస్తూన్నాను ఏమైతే అవ్వని చూసుకుందామని వావ్ సో ఎక్సలెంట్ నాకు చాలా బాగా నచ్చింది సార్ ఇప్పుడు మీరు చేపించిన ప్రక్రియ ఫస్ట్ గేర్ సెకండ్ గేర్ ఫోర్త్ గేర్ ఇస్ కంప్లీట్లీ ఇంటు ద ప్రాసెస్","వావ్ దట్స్ అమేజింగ్ ధనా గారు ఈ మీరు చక్కగా గ అన్నీ కూడా ఏవైతే నేర్చుకుంటున్నామో ఆ జ్ఞానాన్నంతా ఇంటిగ్రేట్ చేసుకుంటున్నారు.","ఫస్ట్ మనం శ్రవణము మననము నిధిజాస దాన్ని అనుభూతి చెందాలి మనం ఏదైతే నేర్చుకుంటున్నామో దాని అనుభవం అనుభూతి మనలో రావాలి లోపల వస్తేనే మీరు అది పొందగలుగుతున్నారు కాబట్టే మీరు చక్కగా ఆ ఆ స్థితుల్ని ఆ గొప్ప జ్ఞానాన్ని ఇప్పుడు ఆ ఉదృత ఎంతున్నా కూడా ఒక గొప్ప జ్ఞానం కలిగింది మీలో అదేమి డేంజరస్ కాదు సేఫ్ ఫీలింగ్ దట్ ఇస్ ద మోస్ట్ సేఫెస్ట్ ఫీలింగ్ అన్నమాట జనరల్గా ఆ పరాశక్తి విజృంభణ చాలా భయపడతారు చాలామంది కుండలిని శక్తి యొక్క విజృంభణ చాలా భయపడతారు కానీ ఆవిడ కైండెస్ట్ మాస్టర్ ఆగుణంతో","ఉన్నటువంటి మాస్టర్ సో కచ్చితంగా ఎంత అద్భుతమైన ఇంటిగ్రేషన్ ఇది సో ఈ స్మాల్ డౌట్ ఏమవస్తుందంటే సార్ ఆ ప్రక్రియ జరుగుతున్నప్పుడు నా శరీరం అలిసిపోతుంది అరే నేను లేసేస్తాను మళ్ళీ కూర్చుంటాను అని చెప్తాను రిలాక్స్ వచ్చేస్తుంది సార్ నేను అనుకున్న వెంటనే రిలాక్స్ వచ్చేస్తుంది ఓకే యు కం బ్యాక్ వవిల్ సీ అగైన్ అన్నట్టుగా అనిపిస్తుంది సార్ అంతా ఓకే కదా సార్ అంతా ఓకే దట్స్ ఓకే ఎందుకంటే ఒక స్థితి తర్వాత మనం ఆ బాహ్యంలోకి వచ్చేయాల అనిపిస్తుంది కదా దట్స్ ఓకే మనం ఏంటంటే ఆ మోమెంట్ లో కొంత వన్","మినిట్ టూ మినిట్స్ ప్రొలాంగ్ చేయాల వెంటనే కొంచెం ఆ స్థితిలో ఉంటూ గ్రాడ్ువల్ గా రావాలి ఎప్పుడు కూడా వెంటనే భయంలోకి వెంటనే ఫాస్ట్ గా రాకూడదు.","ఒకసారి అది జస్ట్ ఒక బ్రింక్ ఆ మోమెంట్ వెరీ ప్రెషియస్ మోమెంట్ అన్నమాట ఒకోసారి అది హోల్డ్ చేయగలగాలి ఆ స్థితి కొంచెం సేపు వన్ ఎక్స్ట్రా మనం చెప్తాం కదా అన్ ఎక్స్ట్రా మైల్ వాక్ చేద్దాము ఇంకొక వన్ మోర్ ఎక్స్ట్రా మైల్ అట్లానే వన్ మోర్ మినిట్ సాధనలో కూడా వన్ మోర్ మినిట్ మన టాలరెన్స్ లెవెల్స్ ఇంకొక స్థాయికి పెంచుకోవాలిన్నమాట వచ్చేయాల అనిపిస్తుంది కానీ కొంచెం ఒక నిమిషం ఎక్కువ వెయిట్ చేయండి ఆ వన్ మినిట్ లోనే చాలా జరుగుతాయి.","ఓకే థాంక్యూ దాన గారు మీరు మొన్న అహింసా ధ్యాన మహాసభల్లో కలిసాం కదా మీ అందరికీ చెప్పాలి ఒక అనుభవం చాలా చక్కని అనుభవం మాకు కలిగింది. ఆ రోజు మేము కూడా ఇంట్లో నుంచి బయలుదేరాం ఆ జాన్ మహాసభలో అహింస గురించి శాఖహార జగత్తు దీని గురించి అక్కడ ఒక క్లాస్ మేము ఇవ్వాలన్నమాట లక్ష్మీ మేడమ నేను హారిక గారు పవన్ గారు కూడా వచ్చారు మమ్మల్ని ఆ కంపెనీ చేయడానికి కార్ తీసుకొచ్చారు వారు కానీ కారు పాడైపోయింది కారు నడవట్లేదు టైం ఏమో తక్కువ ఉంది ఆ ప్రాంతానికి మేము చేరుకోవాలి హైదరాబాద్లో అక్కడికి వెళ్ళాలంటే ఈజీగా 45 మినిట్స్ పడుతుంది వన్ అవర్ పడుతుంది."]$d6tes6json$::jsonb,
