from public.days d
join public.series s on s.id = d.series_id
where s.slug = 'devi-navaratrula-jnanam' and d.day_number = 10 and d.language = 'te'
on conflict (day_id, section_order) do update
set id = excluded.id, title = excluded.title, content = excluded.content, minutes = excluded.minutes, updated_at = now();

insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '566bac17-12a6-4cba-a431-3a369ec69d79'::uuid,
